<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/functions.php';require_role(['admin']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$date=$_POST['expense_date']??date('Y-m-d');$category=trim($_POST['category']??'');$description=trim($_POST['description']??'');$amount=(float)($_POST['amount']??0);if($category===''||$description===''||$amount<=0)$error='Enter an expense category, description, and amount greater than zero.';else{$st=$pdo->prepare('INSERT INTO expenses(expense_date,category,description,amount) VALUES(?,?,?,?)');$st->execute([$date,$category,$description,$amount]);header('Location: reports.php');exit;}}
$period=$_GET['period']??'daily';if(!in_array($period,['daily','weekly','monthly','annual'],true))$period='daily';$today=date('Y-m-d');$from=$today;$to=$today;if($period==='weekly'){$from=date('Y-m-d',strtotime('monday this week'));$to=date('Y-m-d',strtotime('sunday this week'));}elseif($period==='monthly'){$from=date('Y-m-01');$to=date('Y-m-t');}elseif($period==='annual'){$from=date('Y-01-01');$to=date('Y-12-31');}
$st=$pdo->prepare("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='Completed' AND DATE(created_at) BETWEEN ? AND ?");$st->execute([$from,$to]);$sales=(float)$st->fetchColumn();$st=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE expense_date BETWEEN ? AND ?');$st->execute([$from,$to]);$expensesTotal=(float)$st->fetchColumn();$st=$pdo->prepare('SELECT COUNT(*) FROM orders WHERE DATE(created_at) BETWEEN ? AND ?');$st->execute([$from,$to]);$orderCount=(int)$st->fetchColumn();$st=$pdo->prepare('SELECT COUNT(DISTINCT user_id) FROM orders WHERE DATE(created_at) BETWEEN ? AND ?');$st->execute([$from,$to]);$customers=(int)$st->fetchColumn();$st=$pdo->prepare('SELECT COALESCE(SUM(total_cost),0) FROM purchase_orders WHERE order_date BETWEEN ? AND ?');$st->execute([$from,$to]);$supplierSpend=(float)$st->fetchColumn();$st=$pdo->prepare('SELECT expense_date,category,description,amount FROM expenses WHERE expense_date BETWEEN ? AND ? ORDER BY expense_date DESC');$st->execute([$from,$to]);$expenseRows=$st->fetchAll();$inventory=$pdo->query('SELECT COUNT(*) product_count,COALESCE(SUM(stock),0) total_units,COALESCE(SUM(stock*price),0) retail_value,SUM(stock<=5) low_stock FROM products')->fetch();$supplierCount=(int)$pdo->query('SELECT COUNT(*) FROM suppliers')->fetchColumn();$customerCount=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();$pageTitle='Reports & Expenses';include __DIR__.'/../includes/header.php';?>
<div class="admin-shell"><h1>REPORTS & EXPENSES</h1><nav class="admin-nav"><a href="index.php">Dashboard</a><a href="products.php">Products</a><a href="categories.php">Categories</a><a href="suppliers.php">Suppliers</a><a href="inventory.php">Inventory</a><a href="users.php">Users</a></nav><div class="inline-form" style="margin:18px 0"><strong>Report period:</strong><?php foreach(['daily'=>'Daily','weekly'=>'Weekly','monthly'=>'Monthly','annual'=>'Annual'] as $key=>$label):?><a class="btn <?=$period===$key?'btn-blue':''?>" href="?period=<?=$key?>"><?=$label?></a><?php endforeach;?></div><p>Reporting dates: <strong><?=e($from)?></strong> to <strong><?=e($to)?></strong></p><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?>
<div class="stat-grid"><div class="stat-card">Completed sales<strong><?=money($sales)?></strong></div><div class="stat-card">Expenses recorded<strong><?=money($expensesTotal)?></strong></div><div class="stat-card">Supplier purchase orders<strong><?=money($supplierSpend)?></strong></div><div class="stat-card">Orders placed<strong><?=$orderCount?></strong></div><div class="stat-card">Customers with orders<strong><?=$customers?></strong></div><div class="stat-card">Inventory units<strong><?=$inventory['total_units']?></strong></div><div class="stat-card">Inventory retail value<strong><?=money($inventory['retail_value'])?></strong></div><div class="stat-card">Low-stock products<strong><?=$inventory['low_stock']?></strong></div><div class="stat-card">Suppliers / Customers<strong><?=$supplierCount?> / <?=$customerCount?></strong></div></div>
<h2>Supplier report</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Supplier</th><th>Purchase orders in period</th><th>Purchase cost</th></tr></thead><tbody><?php $st=$pdo->prepare("SELECT s.supplier_name,COUNT(po.id) order_count,COALESCE(SUM(po.total_cost),0) spend FROM suppliers s LEFT JOIN purchase_orders po ON po.supplier_id=s.id AND po.order_date BETWEEN ? AND ? GROUP BY s.id ORDER BY spend DESC");$st->execute([$from,$to]);foreach($st as $sr):?><tr><td><?=e($sr['supplier_name'])?></td><td><?=$sr['order_count']?></td><td><?=money($sr['spend'])?></td></tr><?php endforeach;?></tbody></table></div>
<h2>Customer sales report</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Email</th><th>Orders</th><th>Sales total</th></tr></thead><tbody><?php $st=$pdo->prepare("SELECT u.username,u.email,COUNT(o.id) order_count,COALESCE(SUM(CASE WHEN o.status='Completed' THEN o.total ELSE 0 END),0) sales_total FROM users u LEFT JOIN orders o ON o.user_id=u.id AND DATE(o.created_at) BETWEEN ? AND ? WHERE u.role='customer' GROUP BY u.id ORDER BY sales_total DESC");$st->execute([$from,$to]);foreach($st as $cr):?><tr><td><?=e($cr['username'])?></td><td><?=e($cr['email'])?></td><td><?=$cr['order_count']?></td><td><?=money($cr['sales_total'])?></td></tr><?php endforeach;?></tbody></table></div>
<h2>Add expense</h2><section class="form-wrap" style="margin:20px 0;max-width:760px"><form method="post"><div class="field"><label>Date</label><input type="date" name="expense_date" required value="<?=date('Y-m-d')?>"></div><div class="field"><label>Category</label><select name="category"><option>Rent</option><option>Utilities</option><option>Shipping</option><option>Payroll</option><option>Marketing</option><option>Supplies</option><option>Other</option></select></div><div class="field"><label>Description</label><input name="description" required></div><div class="field"><label>Amount (PHP)</label><input type="number" min=".01" step=".01" name="amount" required></div><button class="btn btn-blue">RECORD EXPENSE</button></form></section>
<h2>Expense report</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Category</th><th>Description</th><th>Amount</th></tr></thead><tbody><?php foreach($expenseRows as $ex):?><tr><td><?=e($ex['expense_date'])?></td><td><?=e($ex['category'])?></td><td><?=e($ex['description'])?></td><td><?=money($ex['amount'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/../includes/footer.php';?>